import{_ as i,o as s,c as a,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const o="/bilder/reportdesigner/report-neu-und-veraendern-1.png",l="/bilder/reportdesigner/report-neu-und-veraendern-2.png",d="/bilder/reportdesigner/report-neu-und-veraendern-3.png",u="/bilder/reportdesigner/report-neu-und-veraendern-4.png",p="/bilder/reportdesigner/report-neu-und-veraendern-5.png",g="/bilder/reportdesigner/report-neu-und-veraendern-6.png",h="/bilder/reportdesigner/report-neu-und-veraendern-7.png",R=JSON.parse('{"title":"Einen Report ohne Assistenten erstellen","description":"","frontmatter":{"title":"Einen Report ohne Assistenten erstellen","source_pageid":1565,"source_revision":6679},"headers":[],"relativePath":"reporting/reportdesigner/neuen-report-erstellen.md","filePath":"reporting/reportdesigner/neuen-report-erstellen.md"}'),c={name:"reporting/reportdesigner/neuen-report-erstellen.md"};function m(b,t,f,k,w,_){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="einen-report-ohne-assistenten-erstellen" tabindex="-1">Einen Report ohne Assistenten erstellen <a class="header-anchor" href="#einen-report-ohne-assistenten-erstellen" aria-label="Permalink to &quot;Einen Report ohne Assistenten erstellen&quot;">​</a></h1><p>Erstellen Sie einen leeren Report und bauen Sie eine einfache Liste aus festem Text und einem Datenbankfeld auf. Prüfen Sie das Ergebnis in der Vorschau und speichern Sie anschließend die Vorlage.</p><p>Um die grundlegende Struktur eines Reports und des Reporteditors in <strong>SchILD-NRW 3</strong> kennenzulernen, wird ein neuer, leerer Report erstellt.</p><p><a href="/bilder/reportdesigner/report-neu-und-veraendern-1.png"><img src="'+o+'" alt="Bearbeiten von Reports beziehungsweise Erstellen neuer Reports mit der rechten Maustaste." loading="lazy"></a></p><p><em>Bearbeiten von Reports beziehungsweise Erstellen neuer Reports mit der rechten Maustaste.</em></p><h2 id="den-leeren-report-anlegen" tabindex="-1">Den leeren Report anlegen <a class="header-anchor" href="#den-leeren-report-anlegen" aria-label="Permalink to &quot;Den leeren Report anlegen&quot;">​</a></h2><p>Öffnen Sie die <strong>Reportverwaltung</strong>. Nachdem in den Ordner navigiert wurde, in dem der neue Report entstehen soll, öffnet ein Rechtsklick ein Kontextmenü, über das <strong>Neuen Report erzeugen</strong> gewählt werden kann.</p><h2 id="_1-entwurf-vorschau-und-reportbereiche-kennenlernen" tabindex="-1">1. Entwurf, Vorschau und Reportbereiche kennenlernen <a class="header-anchor" href="#_1-entwurf-vorschau-und-reportbereiche-kennenlernen" aria-label="Permalink to &quot;1. Entwurf, Vorschau und Reportbereiche kennenlernen&quot;">​</a></h2><p><a href="/bilder/reportdesigner/report-neu-und-veraendern-2.png"><img src="'+l+'" alt="Wichtige Elemente des Reporteditors." loading="lazy"></a></p><p><em>Wichtige Elemente des Reporteditors.</em></p><p>Wesentliche Elemente des Editors sind die beiden Schaltflächen <strong>Entwurf</strong> und <strong>Vorschau</strong>. Die Entwurfsansicht dient der Bearbeitung, die Vorschau zeigt das erzeugte Ergebnis.</p><p><strong>Entwurf</strong> bezeichnet die Ansicht, in der Felder als feste Texte, Datenbankinhalte, Bilder, Linien usw. platziert und konfiguriert werden können.</p><p>In der <strong>Vorschau</strong> sehen Sie die Ausgabe mit den aktuellen Einstellungen und Daten. Wechseln Sie bei der Bearbeitung zwischen <strong>Entwurf</strong> und <strong>Vorschau</strong>, um Änderungen am Layout direkt zu prüfen.</p><p>Der Report selbst, im Bild grün markiert, besteht aus drei grundlegenden Bereichen:</p><ul><li><strong>Kopf</strong> – feste Elemente, die über dem eigentlichen Inhalt erscheinen (z. B. Schulkopf oder Kopfzeilen)</li><li><strong>Detailbereich</strong> – enthält das Layout des eigentlichen Reports; hier werden die Daten zeilenweise ausgegeben</li><li><strong>Fuß</strong> – abschließende Elemente wie Seitenzahlen, Datum oder andere Reportinformationen</li></ul><p>Der <strong>Berichtsbaum</strong> (lila markiert) zeigt die Struktur eines Reports hierarchisch an. Er stellt übersichtlich dar, welche Elemente im Kopf-, Detail- und Fußbereich verwendet werden. Gerade bei komplexeren Reports ist dieser Bereich hilfreich.</p><p>Im Beispiel ist zu sehen, dass ein <strong>Label</strong> (ein festes Textfeld) und ein <strong>DBText</strong> (ein Datenbankfeld) in den Detailbereich gelegt wurden. Kopf und Fuß sind leer, daher erscheinen dort keine Einträge im Berichtsbaum.</p>',17),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Der Berichtsbaum wird besonders relevant, wenn Reports mehrfach geschachtelte "),e("strong",null,"Unterberichte"),n(" verwenden. Dies ist z. B. bei Zeugnissen der Fall.")])],-1),r('<h2 id="_2-feste-texte-und-datenbankfelder-einfugen" tabindex="-1">2. Feste Texte und Datenbankfelder einfügen <a class="header-anchor" href="#_2-feste-texte-und-datenbankfelder-einfugen" aria-label="Permalink to &quot;2. Feste Texte und Datenbankfelder einfügen&quot;">​</a></h2><p><a href="/bilder/reportdesigner/report-neu-und-veraendern-3.png"><img src="'+d+'" alt="Die Werkzeugleiste." loading="lazy"></a></p><p><em>Die Werkzeugleiste.</em></p><p>Über die <strong>Werkzeugleiste</strong> werden die Feldtypen bereitgestellt, mit denen ein Report aufgebaut wird.</p><p>Es stehen Werkzeuge für feste Texte (Labels), Datenbankinhalte (DBText), Bilder, Linien, Formen und formatierte Textblöcke zur Verfügung.</p><p>Im Beispiel wurde hervorgehoben, wie ein festes Textfeld platziert wird: dazu wird das entsprechende Werkzeug angeklickt und anschließend an die gewünschte Stelle im Report geklickt. Das Feld kann danach noch verschoben werden.</p><p>Labels können mit beliebigem Text gefüllt werden, hier z. B. mit „Name und Vorname“. Dies erfolgt entweder per Doppelklick auf das Label oder über die Werkzeugleiste.</p>',7),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Im Reporteditor heißen feste Textfelder "),e("strong",null,"Label"),n(" und werden fortlaufend nummeriert (Label1, Label2, ...). Dies gilt ebenso für andere Feldarten, z. B. "),e("strong",null,"Line1"),n(", "),e("strong",null,"Line2"),n(" usw. für Linienobjekte.")])],-1),r('<h2 id="_3-datenquelle-und-datenfeld-zuweisen" tabindex="-1">3. Datenquelle und Datenfeld zuweisen <a class="header-anchor" href="#_3-datenquelle-und-datenfeld-zuweisen" aria-label="Permalink to &quot;3. Datenquelle und Datenfeld zuweisen&quot;">​</a></h2><p>In Lila wurde ein Datenbankfeld (<strong>DBText</strong>) platziert. Dazu wird in der Werkzeugleiste <strong>DBText</strong> gewählt und im Report abgelegt. Wird das Feld aktiviert, kann oben eine passende <strong>Datenquelle</strong> ausgewählt werden.</p><p>Im Beispiel wird die Datenquelle <strong>Schueler</strong> verwendet. Diese enthält u. a. Stammdaten wie Name, Geburtsdatum, Klasse, Jahrgang und Bildungsgang.</p><p>Aus dem Dropdown-Menü wird anschließend ein konkretes <strong>Datenfeld</strong> gewählt, im Beispiel das Feld <strong>NameVorname</strong>.</p><p><a href="/bilder/reportdesigner/report-neu-und-veraendern-4.png"><img src="'+u+'" alt="Der einfache Report in der Vorschau. Noch enthält unser Report einen Fehler." loading="lazy"></a></p><p><em>Der einfache Report in der Vorschau. Noch enthält unser Report einen Fehler.</em></p><p>Nach einem Klick auf <strong>Vorschau</strong> wird ein Report erzeugt.</p><p>Für jede Person im Container links entsteht eine Zeile, die aus dem festen Textfeld „Name und Vorname“ und dem Datenbankfeld <strong>NameVorname</strong> besteht.</p><p>Allerdings ist das Feld im Beispiel so schmal, dass längere Namen abgeschnitten werden. Dieser Fehler wird im nächsten Schritt korrigiert.</p><h2 id="_4-feldbreiten-im-kontextmenu-anpassen" tabindex="-1">4. Feldbreiten im Kontextmenü anpassen <a class="header-anchor" href="#_4-feldbreiten-im-kontextmenu-anpassen" aria-label="Permalink to &quot;4. Feldbreiten im Kontextmenü anpassen&quot;">​</a></h2><p><a href="/bilder/reportdesigner/report-neu-und-veraendern-5.png"><img src="'+p+'" alt="Automatische Größenanpassung des DBText-Feldes." loading="lazy"></a></p><p><em>Automatische Größenanpassung des DBText-Feldes.</em></p><p>Mit einem Klick auf <strong>Entwurf</strong> ist der Report wieder bearbeitbar.</p><p>Über einen Rechtsklick auf das <strong>DBText</strong>-Feld wird <strong>Automatische Größenanpassung</strong> gewählt. Das Feld passt sich nun automatisch in der Breite an den jeweiligen Inhalt an.<br> Ein erneuter Klick auf <strong>Vorschau</strong> erzeugt ein besseres und korrekt lesbares Ergebnis.</p><p><a href="/bilder/reportdesigner/report-neu-und-veraendern-6.png"><img src="'+g+'" alt="Automatische Größenanpassung des DBText-Feldes." loading="lazy"></a></p><p><em>Automatische Größenanpassung des DBText-Feldes.</em></p><p>Dieses Beispiel zeigt, wie Felder in einen Report gezogen werden können und wie sie über Werkzeugleiste oder Kontextmenü konfiguriert werden. Je nach Feldtyp stehen weitere Einstellmöglichkeiten zur Verfügung.</p><h2 id="_5-report-speichern" tabindex="-1">5. Report speichern <a class="header-anchor" href="#_5-report-speichern" aria-label="Permalink to &quot;5. Report speichern&quot;">​</a></h2><p><a href="/bilder/reportdesigner/report-neu-und-veraendern-7.png"><img src="'+h+'" alt="Speichern des Reports." loading="lazy"></a></p><p><em>Speichern des Reports.</em></p><p>Der Report kann über <strong>Datei → Speichern</strong> beziehungsweise <strong>Datei → Speichern unter...</strong> gespeichert werden.</p>',21),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Es wird hierbei der Report, also der „Bauplan“, gespeichert. Nicht gespeichert wird das Ergebnis eines konkret erzeugten Reports.")],-1),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Reports können nur verwendet werden, wenn sie im SchILD-Reportverzeichnis – oder in dessen Unterordnern – abgelegt werden.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Einen_neuen_Report_erstellen",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6679.")],-1)])])}const v=i(c,[["render",m]]);export{R as __pageData,v as default};
